parameters.jsCode:
// 1. Get the TZ from the 'Set TZ' node, fallback to system TZ if not found
const localZone = $node["Set TZ"].json.timezone || $workflow.timezone;

// 2. Define range based on that specific Travel TZ
const startRange = $today.setZone(localZone).plus({ days: 1 }).startOf('day');
const endRange = startRange.plus({ days: 1 });

const icsData = $input.item.json.data; 
if (!icsData) return [];

const lines = icsData.split(/\r?\n/);
const events = [];
let currentEvent = null;

for (const line of lines) {
  const cleanLine = line.trim();
  if (cleanLine.startsWith('BEGIN:VEVENT')) {
    currentEvent = {};
  } else if (cleanLine.startsWith('END:VEVENT')) {
    if (currentEvent.DTSTART) {
      const rawDate = currentEvent.DTSTART.replace(/[^0-9TZ]/g, '');

      let eventDate;
      if (rawDate.includes('T')) {
        // Parse UTC and convert to the Travel TZ
        eventDate = DateTime.fromFormat(rawDate, "yyyyMMdd'T'HHmmss'Z'", { zone: 'utc' }).setZone(localZone);
      } else {
        eventDate = DateTime.fromFormat(rawDate, "yyyyMMdd", { zone: localZone });
      }

      // Filter based on the 24h window of the Travel TZ
      if (eventDate.isValid && eventDate >= startRange && eventDate < endRange) {
        currentEvent.local_start = eventDate.toFormat('yyyy-MM-dd HH:mm:ss');

        if (currentEvent.DTEND) {
          const rawEnd = currentEvent.DTEND.replace(/[^0-9TZ]/g, '');
          currentEvent.local_end = DateTime.fromFormat(rawEnd, "yyyyMMdd'T'HHmmss'Z'", { zone: 'utc' })
            .setZone(localZone)
            .toFormat('yyyy-MM-dd HH:mm:ss');
        }
        events.push({ json: currentEvent });
      }
    }
    currentEvent = null;
  } else if (currentEvent && cleanLine.includes(':')) {
    const [rawKey, ...valParts] = cleanLine.split(':');
    const key = rawKey.split(';')[0]; // Standardized key
    currentEvent[key] = valParts.join(':');
  }
}

return events;
